import { describe, expect, it } from 'vitest';
import { buildingArt, buildingHpBarY } from './buildingArt.js';

/**
 * GATE-02 pinned the gate to its own 320x360 sheet (`buildings/portal.png`).
 *
 * There is deliberately no PNG hash here: the art is regenerated by
 * `scripts/process_generated_assets.py`, and the contract this test protects is
 * the texture key, the lift and the bar height, not the bytes.
 */
describe('portal artwork', () => {
  it('draws the generated gate sheet when it was preloaded', () => {
    expect(buildingArt('PORTAL', () => true)).toEqual({
      textureKey: 'building_PORTAL',
      offsetY: -140,
      scale: 1
    });
  });

  it('asks the texture manager for its own key and nothing else', () => {
    // Pins D5: no `building_TOWER` probe, no second lookup that could smuggle
    // the old placeholder back in.
    const asked: string[] = [];
    buildingArt('PORTAL', (key) => {
      asked.push(key);
      return true;
    });
    expect(asked).toEqual(['building_PORTAL']);
  });

  it('never falls back to the watch tower, even when that sheet exists', () => {
    // The old placeholder borrowed `building_TOWER` and tinted it purple. A
    // missing portal sheet must use the procedural fallback instead, which also
    // keeps the tower's own row untouched.
    const art = buildingArt('PORTAL', (key) => key === 'building_TOWER');
    expect(art).toEqual({ textureKey: 'b_tower', offsetY: -90, scale: 1 });
  });

  it('keeps the procedural fallback when nothing was preloaded', () => {
    expect(buildingArt('PORTAL', () => false)).toEqual({
      textureKey: 'b_tower',
      offsetY: -90,
      scale: 1
    });
  });

  it('places the bar above the measured artwork top', () => {
    // offsetY (-140) - canvas height / 2 (180) + measured topInset (4) - gap (10).
    // `topInset` comes from `process_generated_assets.py --check`; the gate art
    // is 356 px tall on a 360 px canvas, so four rows are empty.
    expect(buildingHpBarY('PORTAL')).toBe(-326);
  });
});
